import '@design-schema/lit';
import { html } from 'lit';

html`
  <div style="inline-size: min(100%, 36rem)">
    <ds-alert
      live="off"
      heading="Changes saved"
      @dismiss=${(event: Event) => (event.target as HTMLElement).remove()}
    >
      <ds-text>Your notification preferences apply to every device you are signed in on.</ds-text>
    </ds-alert>
  </div>
`;

