import * as React from 'react';
import { Alert } from '@design-schema/rn';

function Example() {
  const [visible, setVisible] = React.useState(true);
  return visible ? <Alert heading="Changes saved" dismissible onDismiss={() => setVisible(false)}>Your notification preferences apply from the next digest.</Alert> : <></>;
}

<Example />

